package matteroverdrive.menu;
import matteroverdrive.blockentity.StarMapBlockEntity;import matteroverdrive.registry.ModBlocks;import matteroverdrive.registry.ModMenus;import net.minecraft.core.BlockPos;import net.minecraft.network.FriendlyByteBuf;import net.minecraft.world.entity.player.Inventory;import net.minecraft.world.entity.player.Player;import net.minecraft.world.inventory.AbstractContainerMenu;import net.minecraft.world.inventory.ContainerData;import net.minecraft.world.inventory.ContainerLevelAccess;import net.minecraft.world.inventory.SimpleContainerData;import net.minecraft.world.inventory.Slot;import net.minecraft.world.item.ItemStack;import net.minecraft.world.level.block.entity.BlockEntity;
public class StarMapMenu extends AbstractContainerMenu{private final StarMapBlockEntity map;private final ContainerData data;public StarMapMenu(int id,Inventory inv,FriendlyByteBuf b){this(id,inv,find(inv,b.readBlockPos()),new SimpleContainerData(42));}public StarMapMenu(int id,Inventory inv,StarMapBlockEntity map){this(id,inv,map,map.dataFor(inv.player));}private StarMapMenu(int id,Inventory inv,StarMapBlockEntity map,ContainerData data){super(ModMenus.STAR_MAP.get(),id);this.map=map;this.data=data;for(int r=0;r<3;r++)for(int c=0;c<9;c++)addSlot(new Slot(inv,c+r*9+9,8+c*18,148+r*18));for(int c=0;c<9;c++)addSlot(new Slot(inv,c,8+c*18,206));addDataSlots(data);}private static StarMapBlockEntity find(Inventory inv,BlockPos pos){BlockEntity be=inv.player.level().getBlockEntity(pos);return be instanceof StarMapBlockEntity map?map:new StarMapBlockEntity(pos,ModBlocks.get("star_map").get().defaultBlockState());}@Override public boolean stillValid(Player p){return stillValid(ContainerLevelAccess.create(p.level(),map.getBlockPos()),p,ModBlocks.get("star_map").get());}@Override public ItemStack quickMoveStack(Player p,int i){return ItemStack.EMPTY;}public int active(){return data.get(0);}public int complete(){return data.get(1);}public int currentQuadrant(){return data.get(2);}public int currentStar(){return data.get(3);}public int currentPlanet(){return data.get(4);}public int destinationQuadrant(){return data.get(5);}public int destinationStar(){return data.get(6);}public int destinationPlanet(){return data.get(7);}public int travelRemaining(){return data.get(8);}public int travelDuration(){return data.get(9);}public boolean traveling(){return data.get(10)!=0;}public int encounterCode(){return data.get(11);}public int encounterRemaining(){return data.get(12);}public boolean encounterResolved(){return data.get(13)!=0;}public int fleetHull(){return data.get(14);}public int fleetShield(){return data.get(15);}public int fleetFirepower(){return data.get(16);}public boolean fleetCombat(){return data.get(17)!=0;}public int enemyHull(){return data.get(18);}public int enemyMaxHull(){return data.get(19);}public int fleetVictories(){return data.get(20);}public int fleetAttackCooldown(){return data.get(21);}public int scoutShips(){return data.get(22);}public int colonizerShips(){return data.get(23);}public int buildAction(){return data.get(24);}public int buildRemaining(){return data.get(25);}public int currentOwnerState(){return data.get(26);}public boolean currentHasBase(){return data.get(27)!=0;}public boolean currentHasFactory(){return data.get(28)!=0;}public int currentHangars(){return data.get(29);}public int currentFleetCapacity(){return data.get(30);}public int currentExtractors(){return data.get(31);}public int currentGenerators(){return data.get(32);}public int currentResidential(){return data.get(33);}public int currentEnergyProduction(){return data.get(34);}public int currentMatterProduction(){return data.get(35);}public int currentPopulation(){return data.get(36);}public int currentHappinessHundredths(){return data.get(37);}public int currentBuildingCapacity(){return data.get(38);}public int currentBuildingCount(){return data.get(39);}public int scoutInTransit(){return data.get(40);}public int colonizerInTransit(){return data.get(41);}public BlockPos mapPos(){return map.getBlockPos();}}
